(()=>{const app=document.querySelector('#app'),path=location.pathname;const nav=[['Home','/'],['Pricing','/pricing/'],['Reseller','/reseller/'],['Apps','/apps/'],['Guides','/guides/'],['Blog','/blog/'],['Contact','/contact/']];const features=['Instant activation','Up to +22,000 channels','Up to +88,000 VODs, Series','0.1 Credit = 1 Month','0.3 Credit = 3 Months','0.5 Credit = 6 Months','1 Credit = 12 Months','24/7 support','Full API access','Own domain / white-label support'];const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const shell=content=>`<header class="top"><div class="wrap topin"><a class="brand" href="/"><img src="/assets/tivione.webp" alt="Tivione IPTV">Tivione <b>IPTV</b></a><button class="mobile" aria-label="Menu">☰</button><nav class="nav">${nav.map(([n,u])=>`<a class="${path===u?'active':''}" href="${u}">${n}</a>`).join('')}<a class="button" href="/pricing/">Get Started</a><select class="language" aria-label="Language"><option>English</option><option>Français</option><option>Español</option><option>العربية</option></select></nav></div></header><main>${content}</main><footer class="footer"><div class="wrap footergrid"><div><a class="brand" href="/"><img src="/assets/tivione.webp" alt="Tivione IPTV">Tivione <b>IPTV</b></a><p>Premium streaming plans, player guidance and scalable reseller tools.</p></div><div><strong>Explore</strong>${nav.slice(1).map(([n,u])=>`<a href="${u}">${n}</a>`).join('')}</div><div><strong>Information</strong><a href="/about/">About</a><a href="/privacy/">Privacy</a><a href="/refund/">Refund</a><a href="/terms/">Terms</a></div></div></footer>`;const pageHead=(eyebrow,title,text)=>`<section class="pagehead"><div class="wrap"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="lead">${text}</p></div></section>`;const plan=(name,price)=>`<article class="card"><h3>${name}</h3><div class="price">€${price}</div><ul class="list"><li>Live channels & global EPG</li><li>Movies and TV series</li><li>Major device support</li><li>Player setup guides</li></ul><a class="button" href="/contact/">Request this plan</a></article>`;const plans=`<section><div class="wrap"><div class="head"><span class="eyebrow">Clear subscription choices</span><h2>Find your viewing plan</h2><p class="muted">Pick a duration, review compatible devices, then contact the team through the site.</p></div><div class="grid five">${plan('1 Month',19)}${plan('3 Months',29)}${plan('6 Months',39)}${plan('12 Months',65)}${plan('24 Months',99)}</div></div></section>`;const home=`<section class="hero"><div class="wrap"><span class="eyebrow">Tivione IPTV global network</span><h1>Your screen.<br>Your time.<br>Your Tivione.</h1><p class="lead">Ultra-stable streaming, global delivery routes and straightforward player setup for the devices you use every day.</p><div class="actions"><a class="button" href="/pricing/">Explore plans</a><a class="button alt" href="/reseller/">Explore reseller</a></div><div class="chips"><span class="chip">Live channels & global EPG</span><span class="chip">Premium sports coverage</span><span class="chip">Movies & TV series</span></div></div></section><section><div class="wrap"><div class="head"><span class="eyebrow">Made for your setup</span><h2>Less searching. More watching.</h2><p class="muted">Choose a plan, choose a compatible player and follow a clear device guide.</p></div><div class="grid three"><article class="card feature"><div class="num">01</div><h3>Choose a plan</h3><p>Five clear durations including the 24-month plan at €99.</p><a href="/pricing/">View pricing →</a></article><article class="card feature"><div class="num">02</div><h3>Install your player</h3><p>Find app codes, direct downloads and device-specific steps.</p><a href="/apps/">View apps →</a></article><article class="card feature"><div class="num">03</div><h3>Build your business</h3><p>Flexible credits, API access and custom-domain support for resellers.</p><a href="/reseller/">View reseller →</a></article></div></div></section>${plans}<section><div class="wrap band"><div><span class="eyebrow">Built to scale</span><h2>Reseller tools for growing teams</h2><p>Activation, API access, credit-based durations and own-domain support.</p></div><a class="button" href="/reseller/">See reseller packages</a></div></section>`;const reseller=`${pageHead('Tivione IPTV reseller','Tivione IPTV Reseller Packages','Launch, manage and scale an IPTV business with flexible credits, dedicated support and professional tools.')}<section><div class="wrap"><div class="grid three"><article class="card"><h3>10 Credits</h3><div class="price">€190</div><p>Start with a clear package for your first customers.</p><a class="button" href="/contact/">Request 10 credits</a></article>${['20 Credits','50 Credits','100 Credits','Grow package'].map(n=>`<article class="card"><h3>${n}</h3><p>Talk to the team through the contact page for a tailored package.</p><a class="button" href="/contact/">Contact sales</a></article>`).join('')}</div></div></section><section><div class="wrap"><div class="head"><span class="eyebrow">Server features</span><h2>Everything included with reseller access</h2></div><div class="grid three">${features.map((f,i)=>`<article class="card feature"><div class="num">${String(i+1).padStart(2,'0')}</div><h3>${f}</h3><p>Designed for a practical, supported reseller workflow.</p></article>`).join('')}</div></div></section>`;const appsData=[['IBO Player Pro','2701638',''],['Smart STB','8796547',''],['IPTV Smarters','5926554','http://tivi-center.net/app/apk/TiviOne-Smart.apk'],['TiviMate','8208106','http://tivi-center.net/app/apk/TIVIMATE.apk'],['Wave','1087596','http://tivi-center.net/app/apk/TIVI-MATE-Wave.apk'],['Purple Player','7067392','http://tivi-center.net/app/apk/TIVI-ONEpur.apk']];const apps=`${pageHead('Compatible players','Apps & installation','Use a compatible player. Open the guide page for setup steps, or use the listed app resources.')}<section><div class="wrap grid three apps">${appsData.map(([n,c,u])=>`<article class="card"><img src="/assets/network-background.png" alt="${n}"><h3>${n}</h3><p><strong>Downloader Code:</strong> ${c}</p>${u?`<a class="button" href="${u}">Download app</a>`:`<a class="button" href="/guides/">Open guide</a>`}</article>`).join('')}</div></section>`;const guides=`${pageHead('Setup guides','Make your device ready','Choose your device type and follow the player setup process.')}<section><div class="wrap grid three">${['Firestick','Smart TV','Android','iPhone & iPad','Windows','MAG & Enigma2'].map(x=>`<article class="card"><h3>${x}</h3><p>Install a compatible player, add the account details provided after activation and check the guide for your device.</p><a class="button" href="/apps/">Choose an app</a></article>`).join('')}</div></section>`;const posts=['IPTV setup guide for beginners','Choose the right IPTV player','Firestick player installation','Improve streaming stability','TiviMate setup guide','Global EPG explained'];const blog=`${pageHead('Tivione IPTV blog','Setup, player & streaming guides','Practical guides to make device setup and player choices simpler.')}<section><div class="wrap grid three apps">${posts.map((p,i)=>`<article class="card"><img src="/assets/network-background.png" alt="${p}"><h3>${p}</h3><p>Practical device preparation, player configuration and home-network tips.</p><a class="button" href="/blog/?article=${encodeURIComponent(p)}">Read more</a></article>`).join('')}</div></section>`;const articleTitle=new URLSearchParams(location.search).get('article');const article=articleTitle?`${pageHead('Tivione IPTV guide',esc(articleTitle),'A detailed setup resource for Tivione IPTV customers.')}<section><article class="wrap article"><img src="/assets/network-background.png" alt="Guide"><h1>${esc(articleTitle)}</h1>${Array(7).fill('Start with a compatible device and a stable home connection. Keep your player updated, enter the supplied connection information exactly as provided and allow time for guides and categories to load. If playback needs attention, check the Wi-Fi signal, restart the player and use the contact page with your device and player name. A clear setup process, current app version and stable local network make a meaningful difference to the viewing experience.').map(p=>`<p>${p}</p>`).join('')}<a class="button" href="/contact/">Contact support</a></article></section>`:'';const contact=`${pageHead('Contact Tivione IPTV','Talk to the team','Use the contact channels below for plan, setup or reseller enquiries.')}<section><div class="wrap grid three"><article class="card"><h3>WhatsApp</h3><p>+212 670-779271</p></article><article class="card"><h3>Telegram</h3><p>@premiumiptvpanelscom</p></article><article class="card"><h3>Email</h3><p>support@reselleriptv.com</p></article></div></section>`;const legal=name=>`${pageHead('Tivione IPTV information',name,'Clear policy and service information for visitors and customers.')}<section><article class="wrap article"><h1>${name}</h1><p>We aim to provide clear, readable information. Use the contact page for questions about plans, setup, service and policies.</p><p>Information submitted through support channels is used to respond to requests and provide help. Service use depends on compatible devices, network conditions and applicable terms.</p></article></section>`;let content=home;if(path==='/pricing/')content=pageHead('Subscriptions','Tivione IPTV Plans','Choose the duration that works for you.')+plans;else if(path==='/reseller/')content=reseller;else if(path==='/apps/')content=apps;else if(path==='/guides/')content=guides;else if(path==='/blog/')content=article||blog;else if(path==='/contact/')content=contact;else if(['/privacy/','/refund/','/terms/','/about/'].includes(path))content=legal(path.slice(1,-1).replace(/^./,x=>x.toUpperCase()));app.innerHTML=shell(content);const menu=document.querySelector('.mobile'),navEl=document.querySelector('.nav');menu?.addEventListener('click',()=>navEl.classList.toggle('open'));const select=document.querySelector('.language');select.value=localStorage.getItem('tivione-language')||'English';select.addEventListener('change',e=>localStorage.setItem('tivione-language',e.target.value));})();
